+  const url = new URL(path, "http://x");
+  if (url.pathname === "/items") {
+    let offset = 0;
+    let limit = items.length;
+    for (const [key, raw] of url.searchParams) {
+      if (key === "offset") {
+        if (!/^\d+$/.test(raw))
+          return httpError(400, "invalid_offset", "offset must be a whole number from 0.");
+        offset = Number(raw);
+      } else if (key === "limit") {
+        if (!/^\d+$/.test(raw) || Number(raw) < 1 || Number(raw) > 50)
+          return httpError(400, "invalid_limit", "limit must be a whole number from 1 to 50.");
+        limit = Number(raw);
+      } else {
+        return httpError(400, "invalid_query", "Invalid query parameter.");
+      }
+    }
+    return { status: 200, body: items.slice(offset, offset + limit) };
+  }
+  if (url.pathname === "/expiring")
     return {
